import { useState } from 'react';
import {
  JxCard,
  JxStepper,
  JxStep,
  JxInput,
  JxButton,
  JxStack,
  JxText,
} from '@jinx-ui/react';

interface RegistrationFormValues {
  fullName: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
}

interface RegistrationWizardProps {
  onSubmit: (values: RegistrationFormValues) => void;
}

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const INITIAL_VALUES: RegistrationFormValues = {
  fullName: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [currentStep, setCurrentStep] = useState(0);
  const [values, setValues] = useState<RegistrationFormValues>(INITIAL_VALUES);

  const updateField = (field: keyof RegistrationFormValues) => (value: string) => {
    setValues((prev) => ({ ...prev, [field]: value }));
  };

  const isFirstStep = currentStep === 0;
  const isLastStep = currentStep === STEPS.length - 1;

  const goBack = () => {
    if (!isFirstStep) {
      setCurrentStep((step) => step - 1);
    }
  };

  const goNext = () => {
    if (!isLastStep) {
      setCurrentStep((step) => step + 1);
    }
  };

  const handleSubmit = () => {
    onSubmit(values);
  };

  return (
    <JxCard className="jx-p-lg" style={{ maxWidth: 'var(--jx-size-md, 480px)' }}>
      <JxStack direction="column" gap="lg">
        <JxStepper currentStep={currentStep}>
          {STEPS.map((label, index) => (
            <JxStep key={label} index={index} label={label} completed={index < currentStep} />
          ))}
        </JxStepper>

        {currentStep === 0 && (
          <JxStack direction="column" gap="md">
            <JxText variant="heading-sm">Контакты</JxText>
            <JxInput
              label="Полное имя"
              value={values.fullName}
              onChange={updateField('fullName')}
              placeholder="Иван Иванов"
            />
            <JxInput
              label="Email"
              type="email"
              value={values.email}
              onChange={updateField('email')}
              placeholder="you@example.com"
            />
            <JxInput
              label="Телефон"
              type="tel"
              value={values.phone}
              onChange={updateField('phone')}
              placeholder="+7 900 000-00-00"
            />
          </JxStack>
        )}

        {currentStep === 1 && (
          <JxStack direction="column" gap="md">
            <JxText variant="heading-sm">Адрес</JxText>
            <JxInput
              label="Страна"
              value={values.country}
              onChange={updateField('country')}
              placeholder="Россия"
            />
            <JxInput
              label="Город"
              value={values.city}
              onChange={updateField('city')}
              placeholder="Москва"
            />
            <JxInput
              label="Улица и дом"
              value={values.street}
              onChange={updateField('street')}
              placeholder="ул. Примерная, 1"
            />
            <JxInput
              label="Индекс"
              value={values.zip}
              onChange={updateField('zip')}
              placeholder="123456"
            />
          </JxStack>
        )}

        {currentStep === 2 && (
          <JxStack direction="column" gap="md">
            <JxText variant="heading-sm">Проверка</JxText>
            <JxStack direction="column" gap="xs">
              <JxText variant="body-sm" style={{ color: 'var(--jx-color-text-secondary)' }}>
                Контакты
              </JxText>
              <JxText variant="body-md">{values.fullName || '—'}</JxText>
              <JxText variant="body-md">{values.email || '—'}</JxText>
              <JxText variant="body-md">{values.phone || '—'}</JxText>
            </JxStack>
            <JxStack direction="column" gap="xs">
              <JxText variant="body-sm" style={{ color: 'var(--jx-color-text-secondary)' }}>
                Адрес
              </JxText>
              <JxText variant="body-md">
                {[values.country, values.city, values.street, values.zip]
                  .filter(Boolean)
                  .join(', ') || '—'}
              </JxText>
            </JxStack>
          </JxStack>
        )}

        <JxStack direction="row" justify="space-between">
          <JxButton variant="secondary" onClick={goBack} disabled={isFirstStep}>
            Назад
          </JxButton>
          {isLastStep ? (
            <JxButton variant="primary" onClick={handleSubmit}>
              Отправить
            </JxButton>
          ) : (
            <JxButton variant="primary" onClick={goNext}>
              Дальше
            </JxButton>
          )}
        </JxStack>
      </JxStack>
    </JxCard>
  );
}

